INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Wirtschaftliche Aspekte > Kalkulation > Buchführungsarten
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die doppelte Buchführung für alle Unternehmen gesetzlich vorgeschrieben?', 2, '[{"text": "Nein", "correct": true, "because": "Kleinunternehmer können einfache Buchführung nutzen"}, {"text": "Ja", "correct": false, "because": "Nicht für alle verpflichtend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die einfache Buchführung auch Gewinne und Verluste darstellen?', 2, '[{"text": "Ja", "correct": true, "because": "Zeigt Einnahmen und Ausgaben"}, {"text": "Nein", "correct": false, "because": "Einfache Methode ist ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen bei der doppelten Buchführung alle Geschäftsvorfälle doppelt erfasst werden?', 2, '[{"text": "Ja", "correct": true, "because": "Grundprinzip der doppelten Erfassung"}, {"text": "Nein", "correct": false, "because": "Doppelte Erfassung ist zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die einfache Buchführung für Kapitalgesellschaften wie GmbHs zulässig?', 2, '[{"text": "Nein", "correct": true, "because": "Kapitalgesellschaften müssen doppelte Buchführung nutzen"}, {"text": "Ja", "correct": false, "because": "Gesetzlich ausgeschlossen"}]'),
('00000000-0000-0000-0000-000000000000', 'Können IT-Systeme die Buchführung komplett automatisieren?', 2, '[{"text": "Nein", "correct": true, "because": "Manuelle Eingaben und Kontrollen nötig"}, {"text": "Ja", "correct": false, "because": "Automatisierung begrenzt"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Buchführungsart ist für Einzelunternehmer mit geringem Umsatz geeignet?', 3, '[{"text": "Einfache Buchführung", "correct": true, "because": "Weniger komplex und ausreichend"}, {"text": "Doppelte Buchführung", "correct": false, "because": "Aufwendiger"}, {"text": "Kostenrechnung", "correct": false, "because": "Anderer Zweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip liegt der doppelten Buchführung zugrunde?', 2, '[{"text": "Doppelte Erfassung", "correct": true, "because": "Jeder Vorgang wird auf zwei Konten gebucht"}, {"text": "Einfache Erfassung", "correct": false, "because": "Einfache Buchführung"}, {"text": "Einmalige Buchung", "correct": false, "because": "Nicht doppelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unternehmensform ist gesetzlich zur doppelten Buchführung verpflichtet?', 2, '[{"text": "Aktiengesellschaft (AG)", "correct": true, "because": "Pflicht gemäß HGB"}, {"text": "Einzelunternehmen", "correct": false, "because": "Optional einfach"}, {"text": "Freiberufler", "correct": false, "because": "Einfach möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Dokument wird bei der einfachen Buchführung primär genutzt?', 3, '[{"text": "Einnahmen-Überschuss-Rechnung (EÜR)", "correct": true, "because": "Zeigt Gewinn einfach"}, {"text": "Bilanz", "correct": false, "because": "Doppelte Buchführung"}, {"text": "Kostenstellenrechnung", "correct": false, "because": "Kostenrechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Hauptvorteil der doppelten Buchführung?', 2, '[{"text": "Detaillierte Übersicht", "correct": true, "because": "Zeigt Vermögen und Schulden"}, {"text": "Geringerer Aufwand", "correct": false, "because": "Komplexer"}, {"text": "Schnelle Erstellung", "correct": false, "because": "Zeitaufwendig"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale charakterisieren die doppelte Buchführung?', 4, '[{"text": "Doppelte Erfassung", "correct": true, "because": "Jeder Vorgang zweifach"}, {"text": "Kontenrahmen", "correct": true, "because": "Strukturierte Buchung"}, {"text": "Bilanzierung", "correct": true, "because": "Vermögen und Schulden"}, {"text": "Einfache Summen", "correct": false, "because": "Einfache Buchführung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unternehmen dürfen die einfache Buchführung nutzen?', 3, '[{"text": "Einzelunternehmer", "correct": true, "because": "Mit geringem Umsatz"}, {"text": "Freiberufler", "correct": true, "because": "Wenn nicht bilanzierungspflichtig"}, {"text": "Kleinunternehmer", "correct": true, "because": "Umsatzgrenze beachten"}, {"text": "Aktiengesellschaften", "correct": false, "because": "Doppelte Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die doppelte Buchführung?', 3, '[{"text": "Genauigkeit", "correct": true, "because": "Fehler leichter erkennbar"}, {"text": "Transparenz", "correct": true, "because": "Detaillierte Übersicht"}, {"text": "Gesetzeskonformität", "correct": true, "because": "Für Kapitalgesellschaften"}, {"text": "Geringer Aufwand", "correct": false, "because": "Aufwendiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme können bei der Buchführung auftreten?', 4, '[{"text": "Fehlende Belege", "correct": true, "because": "Erschwert Nachweis"}, {"text": "Falsche Buchungen", "correct": true, "because": "Verfälscht Ergebnisse"}, {"text": "Komplexität", "correct": true, "because": "Besonders bei doppelter Buchführung"}, {"text": "Schnelle Lieferung", "correct": false, "because": "Logistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zur einfachen Buchführung?', 3, '[{"text": "Einnahmen", "correct": true, "because": "Grundlage der EÜR"}, {"text": "Ausgaben", "correct": true, "because": "Grundlage der EÜR"}, {"text": "Gewinnermittlung", "correct": true, "because": "Ziel der einfachen Buchführung"}, {"text": "Bilanz", "correct": false, "because": "Doppelte Buchführung"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die doppelte Buchführung erfordert einen Kontenrahmen. b) Einfache Buchführung ist für GmbHs zulässig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kontenrahmen ja, GmbH doppelt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die EÜR ist ein Ergebnis der einfachen Buchführung. b) Doppelte Buchführung ist weniger genau als einfache.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "EÜR ja, doppelte genauer"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kapitalgesellschaften müssen doppelte Buchführung nutzen. b) IT-Systeme können die Buchführung vollständig ersetzen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kapitalgesellschaften ja, IT unterstützt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die doppelte Buchführung bietet eine detaillierte Übersicht. b) Einfache Buchführung ist für alle Unternehmen ausreichend.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Doppelte ja, einfache begrenzt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fehler in der Buchführung können die Kalkulation verfälschen. b) Freiberufler müssen immer doppelte Buchführung nutzen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehler ja, Freiberufler einfach"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

